[1355] = "Le profil sélectionné a changé. Rouvrez la fenêtre d'importation.",
-- 1609b3f3 English: This import contains Lua code. Only continue if you trust its author. Import
--     opens the code for review; saving the condition can execute it.
[1356] = "Cette importation contient du code Lua. Ne continuez que si vous faites confiance à son auteur. Importer ouvre le code pour vérification ; enregistrer la condition peut l'exécuter.",
-- ae820bc2 English: Use letters, numbers and underscores for the condition identifier.
[1357] = "Utilisez des lettres, des chiffres et des tirets bas pour l'identifiant de condition.",
