[1376] = "Toutes les étiquettes",
-- 08c83906 English: Edit the description, tags, author, realm, email, website and version. Source
--     citations remain separate from your attribution. Use changes updates the rotation draft;
--     Apply the rotation to save it. Cancel or Escape restores this dialog’s opening values.
[1377] = "Modifiez la description, les étiquettes, l'auteur, le royaume, l'e-mail, le site web et la version. Les citations de sources restent séparées de votre attribution. Utiliser les modifications met à jour le brouillon de la rotation ; appliquez la rotation pour l'enregistrer. Annuler ou Échap rétablit les valeurs d'ouverture de cette fenêtre.",
-- 73f5fe1e English: Invalid tags. Use up to 64 tags of 64 characters, separated by commas.
[1378] = "Étiquettes invalides. Utilisez au plus 64 étiquettes de 64 caractères, séparées par des virgules.",
-- 36b7b9b3 English: Separate tags with commas. Use quotes for tags containing commas. Any personal
--     label is allowed.
[1379] = "Séparez les étiquettes par des virgules. Utilisez des guillemets pour les étiquettes contenant des virgules. Tout libellé personnel est autorisé.",
