[1622] = "Décrivez ce que fait cette fonction.",
-- 0d646ec9 English: Add a function or duplicate a packaged helper to edit its source.
[1623] = "Ajoutez une fonction ou dupliquez une fonction utilitaire fournie pour modifier sa source.",
-- aebc00b0 English: LuaWorkbench supplies editing, completion, API knowledge and debugging. Debug
--     runs this buffer explicitly using the test arguments. It does not replace the saved rotation
--     or live callback.
[1624] = "LuaWorkbench fournit l'édition, la complétion, la connaissance de l'API et le débogage. Déboguer exécute explicitement ce tampon avec les arguments de test. Cela ne remplace ni la rotation enregistrée ni la fonction de rappel active.",
-- ac6ddfe4 English: Connected: embedded editing, completion, API knowledge and debugging.
[1625] = "Connecté : édition intégrée, complétion, connaissance de l'API et débogage.",
-- e3b56b53 English: Review the dependency bundle before applying it.
[1626] = "Vérifiez le lot de dépendances avant de l'appliquer.",
-- e0ad4daf English: Function bindings (%d)
[1627] = "Liaisons de fonctions (%d)",
-- 1f10215d English: Aliases are local names in your Lua body. Changing an alias does not rewrite
